   171  static inline int chr_is_valid_rgb(const char format[])
   172  {
   173          int tmp;
   174          for (tmp = 1; tmp < 7; ++tmp) {
   175                  if (!isxdigit(format[tmp]))
   176                          return tmp;
   177          }
   178          return 0;
   179  }
   180
   181  static inline int chr_is_valid_ext(const char format[])
   182  {
   183          if (format[1] < '0' || format[1] > '7')
   184                  return 1;
   185
   186          if (format[1] == '7') {
   187                  if (!isalpha(format[2]) || format[2] == 'y' || format[2] == 'Y'
   188                      || format[2] =='z' || format[2] == 'Z')
   189                          return 2;
   190          } else if (format[1] == '0') {
   191                  if (!isxdigit(format[2]))
   192                          return 2;
   193          } else if (!isalnum(format[2]))
   194                  return 2;
   195
   196          return 0;
   197  }
