   895  THEME_REC *theme_load(const char *setname)
   896  {
   897          THEME_REC *theme, *oldtheme;
   898          struct stat statbuf;
   899          char *fname, *name, *p;
   900
   901          name = g_strdup(setname);
   902          p = strrchr(name, '.');
   903          if (p != NULL && g_strcmp0(p, ".theme") == 0) {
   904                  /* remove the trailing .theme */
   905                  *p = '\0';
   906          }
   907
   908          theme = theme_find(name);
   909
   910          /* check home dir */
   911          fname = g_strdup_printf("%s/%s.theme", get_irssi_dir(), name);
   912          if (stat(fname, &statbuf) != 0) {
   913                  /* check global config dir */
   914                  g_free(fname);
   915                  fname = g_strdup_printf(THEMESDIR"/%s.theme", name);
   916                  if (stat(fname, &statbuf) != 0) {
   917                          /* theme not found */
   918                          g_free(fname);
   919                          g_free(name);
   920                          return theme; /* use the one in memory if possible */
   921                  }
   922          }
   923
   924          if (theme != NULL && theme->last_modify == statbuf.st_mtime) {
   925                  /* theme not modified, use the one already in memory */
   926                  g_free(fname);
   927                  g_free(name);
   928                  return theme;
   929          }
   930
   931          oldtheme = theme;
   932          theme = theme_create(fname, name);
   933          theme->last_modify = statbuf.st_mtime;
   934          if (!theme_read(theme, theme->path)) {
   935                  /* error reading .theme file */
   936                  theme_destroy(theme);
   937                  theme = NULL;
   938          }
   939
   940          if (oldtheme != NULL && theme != NULL) {
   941                  theme_destroy(oldtheme);
   942                  if (current_theme == oldtheme)
   943                          current_theme = theme;
   944                  window_themes_update();
   945          }
   946
   947          g_free(fname);
   948          g_free(name);
   949          return theme;
   950  }
