   989  static int theme_read(THEME_REC *theme, const char *path)
   990  {
   991          CONFIG_REC *config;
   992          THEME_READ_REC rec;
   993          char *str;
   994
   995          config = config_open(path, -1) ;
   996          if (config == NULL) {
   997                  /* didn't exist or no access? */
   998                  str = g_strdup_printf("Error reading theme file %s: %s",
   999                                        path, g_strerror(errno));
  1000                  read_error(str);
  1001                  g_free(str);
  1002                  return FALSE;
  1003          }
  1004
  1005          if (path == NULL)
  1006                  config_parse_data(config, default_theme, "internal");
  1007          else
  1008                  config_parse(config);
  1009
  1010          if (config_last_error(config) != NULL) {
  1011                  str = g_strdup_printf("Ignored errors in theme %s:\n%s",
  1012                                        theme->name, config_last_error(config));
  1013                  read_error(str);
  1014                  g_free(str);
  1015          }
  1016
  1017          theme->default_color =
  1018                  config_get_int(config, NULL, "default_color", -1);
  1019          theme->info_eol = config_get_bool(config, NULL, "info_eol", FALSE);
  1020
  1021          theme_read_replaces(config, theme);
  1022
  1023          if (path != NULL)
  1024                  theme_copy_abstracts(theme, internal_theme);
  1025          theme_read_abstracts(config, theme);
  1026
  1027          rec.theme = theme;
  1028          rec.config = config;
  1029          g_hash_table_foreach(default_formats,
  1030                               (GHFunc) theme_read_modules, &rec);
  1031          config_close(config);
  1032
  1033          return TRUE;
  1034  }
